package main

import (
    "context"
    "encoding/json"
    "fmt"
    "os"

    "github.com/notionhq/notion-client-go/v3"
)

func main() {
    // Create a client
    c := notion.NewClient(os.Getenv("NOTION_API_KEY"))

    // Get the user
    user, err := c.Databases.Query(context.Background(), notion.DatabaseQuery{
        DatabaseId: "YOUR_DATABASE_ID",
        Filter: notion.DatabaseFilter{
            Property: "User",
            RichText: notion.RichTextFilter{
                Equals: "User",
            },
        },
    })
    if err != nil {
        fmt.Println(err)
        return
    }

    // Print the user
    fmt.Println(string(user))
}
